&lt;table class=&quot;Bestiaire&quot;&gt;
&lt;tr&gt;
&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Ettin mythique&lt;div style=&quot;float:right;&quot;&gt;FP 8/RMY 3&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Collines&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Collines.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Froid&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Froid.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Campagnes mythiques p.197&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 4 800
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-G&#233;ant.html&quot; title=&quot;G&#233;ant (sous-type)&quot;&gt;g&#233;ant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;mythique&lt;/a&gt;) de taille G, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +3 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Puanteur-(Capacit&#233;).html&quot; title=&quot;Puanteur (Ext)&quot;&gt;puanteur&lt;/a&gt; (DD 17, 10 rounds)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 22, contact 8, pris au d&#233;pourvu 22 (+3 armure, -1 Dex, +11 naturelle, -1 taille)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 89 (10d8+44)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +2, &lt;b&gt;Vig&lt;/b&gt; +9, &lt;b&gt;Vol&lt;/b&gt; +5
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; deux cerveaux ; &lt;b&gt;RD&lt;/b&gt; 5/&lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Rdepique.html&quot; title=&quot;RD&#233;pique&quot;&gt;&#233;pique&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 12 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; 2 fl&#233;aux d’armes, +13/+13 (2d6+7)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#192; distance&lt;/b&gt; 2 javelines, +5 (1d8+7)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Espace occup&#233;&lt;/b&gt; 3 m ; &lt;b&gt;Allonge&lt;/b&gt; 3 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Charge-Puissante-(Capacit&#233;).html&quot; title=&quot;Charge puissante (Ext)&quot;&gt;charge puissante&lt;/a&gt; (fl&#233;au, 4d6+10), perfection du combat &#224; deux armes, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoir-Mythique-(Capacit&#233;).html&quot; title=&quot;Pouvoir mythique (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;pouvoir mythique&lt;/a&gt; (3/jour, &lt;a class=&quot;pagelink&quot; href=&quot;Mont&#233;e-En-Puissance-(Capacit&#233;).html&quot; title=&quot;Mont&#233;e en puissance (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;mont&#233;e en puissance&lt;/a&gt; +1d6)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 25, &lt;b&gt;Dex&lt;/b&gt; 8, &lt;b&gt;Con&lt;/b&gt; 15, &lt;b&gt;Int&lt;/b&gt; 6, &lt;b&gt;Sag&lt;/b&gt; 10, &lt;b&gt;Cha&lt;/b&gt; 11
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +7, &lt;b&gt;BMO&lt;/b&gt; +15 (+17 pour le &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Renversement.html&quot; title=&quot;renversement&quot;&gt;renversement&lt;/a&gt;), &lt;b&gt;DMD&lt;/b&gt; 24
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;&lt;sup&gt;M&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Encha&#238;nement.html&quot; title=&quot;Encha&#238;nement&quot;&gt;Encha&#238;nement&lt;/a&gt;&lt;sup&gt;M&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Renversement.html&quot; title=&quot;Science du renversement&quot;&gt;Science du renversement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; +8, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12 ; &lt;b&gt;Modificateurs raciaux&lt;/b&gt; +4 en Perception
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; m&#233;lange de g&#233;ant, de gobelin et d’orque
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; collines froides
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation sociale&lt;/b&gt; solitaire, couple, gang (3-6), troupe (1-2 plus 1-2 ours bruns), groupe (3-6 plus 1-2 ours bruns) ou colonie (3-6 plus 1-2 ours bruns et 7-12 &lt;a class=&quot;pagelink&quot; href=&quot;Orque.html&quot; title=&quot;Orque&quot;&gt;orques&lt;/a&gt; ou 9-16 &lt;a class=&quot;pagelink&quot; href=&quot;Gobelin.html&quot; title=&quot;Gobelin&quot;&gt;gobelins&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; standard (&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-Clout&#233;e-(Armure).html&quot; title=&quot;Armure de cuir clout&#233;e&quot;&gt;armure de cuir clout&#233;e&lt;/a&gt;, 2 fl&#233;aux d’armes, 4 &lt;a class=&quot;pagelink&quot; href=&quot;Javeline-(Arme).html&quot; title=&quot;Javeline&quot;&gt;javelines&lt;/a&gt;, autre tr&#233;sor)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Pouvoirs sp&#233;ciaux&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Deux cerveaux (Ext).&lt;/b&gt; Chaque fois que l’ettin mythique tente un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, il fait deux jets et garde le meilleur r&#233;sultat.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Perfection du combat &#224; deux armes (Ext).&lt;/b&gt; Au combat, les ettins utilisent un fl&#233;au ou une javeline dans chaque main. Comme chacune de leurs deux t&#234;tes contr&#244;le un bras, le fait de combattre avec deux armes ne leur impose aucun malus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Degats.html&quot; title=&quot;jet de d&#233;g&#226;t&quot;&gt;d&#233;g&#226;ts&lt;/a&gt;.
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;td&gt;
&lt;div&gt;
&lt;i&gt;Des mouches bourdonnent autour de ce g&#233;ant bestial &#224; deux t&#234;tes et des asticots se tortillent dans les replis de sa chair.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;
L’ettin mythique descend d’un lignage sordide fait de g&#233;ants des collines mythiques, de g&#233;ants de pierre mythiques et d’au moins un orque mythique. Plus col&#233;reux, plus crasseux et plus forts que les autres ettins, c’est un chef parmi les siens et il est tr&#232;s dou&#233; pour garder un groupe ou une colonie soud&#233;e pendant des mois ou des ann&#233;es.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Variantes de l’ettin mythique&lt;a class=&quot;headeranchor&quot; id=&quot;Variantes_de_l’ettin_mythique_0&quot; href=&quot;#Variantes_de_l’ettin_mythique_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Certains ettins mythiques sont &#233;troitement affili&#233;s &#224; l’une de leurs races ancestrales et poss&#232;dent diff&#233;rentes aptitudes mythiques.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ettin de pierre (FP 8/RMy 3).&lt;/b&gt; L’ettin mythique &#224; dominante g&#233;ant de pierre perd ses pouvoirs de &lt;a class=&quot;pagelink&quot; href=&quot;Charge-Puissante-(Capacit&#233;).html&quot; title=&quot;Charge puissante (Ext)&quot;&gt;charge puissante&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Puanteur-(Capacit&#233;).html&quot; title=&quot;Puanteur (Ext)&quot;&gt;puanteur&lt;/a&gt; mais gagne les pouvoirs expert en r&#233;ception de rochers et lancer de rochers du &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-De-Pierre.html&quot; title=&quot;G&#233;ant, G&#233;ant de pierre&quot;&gt;g&#233;ant de pierre&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ettin des collines (FP 8/RMy 3).&lt;/b&gt; L’ettin mythique &#224; dominante g&#233;ant des collines perd ses pouvoirs de &lt;a class=&quot;pagelink&quot; href=&quot;Charge-Puissante-(Capacit&#233;).html&quot; title=&quot;Charge puissante (Ext)&quot;&gt;charge puissante&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Puanteur-(Capacit&#233;).html&quot; title=&quot;Puanteur (Ext)&quot;&gt;puanteur&lt;/a&gt; mais gagne les aptitudes mart&#232;lement du sol et li&#233; &#224; la terre du &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Collines-Mythique.html&quot; title=&quot;G&#233;ant des collines mythique&quot;&gt;g&#233;ant des collines mythique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ettin-orque (FP 8/RMy 3).&lt;/b&gt; L’ettin &#224; dominante orque perd ses pouvoirs &lt;a class=&quot;pagelink&quot; href=&quot;Puanteur-(Capacit&#233;).html&quot; title=&quot;Puanteur (Ext)&quot;&gt;puanteur&lt;/a&gt; et deux cerveaux mais gagne &lt;a class=&quot;pagelink&quot; href=&quot;Rage-Sanguinaire-(Capacit&#233;).html&quot; title=&quot;Rage sanguinaire (Ext)&quot;&gt;rage sanguinaire&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Sauvagerie-F&#233;roce-(Capacit&#233;).html&quot; title=&quot;Sauvagerie f&#233;roce (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;sauvagerie f&#233;roce&lt;/a&gt;.
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
